using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        HttpRequestMessage? capturedRequest = null;
        string? capturedBody = null;

        var handler = new StubHandler(async request =>
        {
            capturedRequest = request;
            capturedBody = await request.Content!.ReadAsStringAsync();
            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = JsonContent.Create(new { status = "approved" }),
            };
        });

        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });

        await gateway.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.NotNull(capturedRequest);
        Assert.Equal(HttpMethod.Post, capturedRequest!.Method);
        Assert.Equal("/v1/authorizations", capturedRequest.RequestUri!.AbsolutePath);

        using var document = JsonDocument.Parse(capturedBody!);
        var root = document.RootElement;
        Assert.Equal("ORD-1", root.GetProperty("reference").GetString());
        Assert.Equal(42.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        var handler = StubHandler.RespondingWith(HttpStatusCode.OK, new { status = "approved" });
        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_declined()
    {
        var handler = StubHandler.RespondingWith(HttpStatusCode.OK, new { status = "declined" });
        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_value_is_treated_as_declined()
    {
        var handler = StubHandler.RespondingWith(HttpStatusCode.OK, new { status = "pending-review" });
        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_from_the_provider_means_the_payment_is_declined_outright()
    {
        var handler = new StubHandler(_ => Task.FromResult(new HttpResponseMessage(HttpStatusCode.PaymentRequired)));
        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_error_from_the_provider_surfaces_as_a_failure_not_a_silent_decline()
    {
        var handler = new StubHandler(_ => Task.FromResult(new HttpResponseMessage(HttpStatusCode.InternalServerError)));
        var gateway = new HttpPaymentGateway(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") });

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None));
    }

    private sealed class StubHandler(Func<HttpRequestMessage, Task<HttpResponseMessage>> respond) : HttpMessageHandler
    {
        public static StubHandler RespondingWith(HttpStatusCode statusCode, object body)
            => new(_ => Task.FromResult(new HttpResponseMessage(statusCode) { Content = JsonContent.Create(body) }));

        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
            => respond(request);
    }
}

